      c2.host_key !== null &&
      c2.host_key.key_type === key.key_type &&
      c2.host_key.fingerprint === key.fingerprint;
    if (!same) return Result.err({ kind: "HostKeyChangedOnRekey" });
    return Result.ok(keyed(c2, kx, algorithms, []));
